-- idempotent sink: processing the same event twice leaves the same result
CREATE TABLE payments (
  event_id    TEXT PRIMARY KEY,
  order_id    TEXT NOT NULL,
  amount      NUMERIC(10, 2) NOT NULL,
  received_at TIMESTAMPTZ NOT NULL
);

INSERT INTO payments (event_id, order_id, amount, received_at)
VALUES (%(event_id)s, %(order_id)s, %(amount)s, %(received_at)s)
ON CONFLICT (event_id) DO NOTHING;
